test('brick: corner hit with equal penetration flips both components', () => {
  // Ball overlapping the bottom-right corner of the brick, penetrating
  // 9 px on each axis: a naive smallest-penetration pick would flip only vx.
  const state = oneBrickState({
    x: 170, y: 118, r: BALL_R, vx: 100, vy: 100, prevX: 171, prevY: 119,
  });
  resolveBrickCollisions(state);
  assert.equal(Math.sign(state.ball.vx), LEFT, 'vx flips at a corner');
  assert.equal(Math.sign(state.ball.vy), UP, 'vy flips at a corner');
  assert.equal(state.bricks[0].alive, false);
});

test('brick: ball is pushed out of the brick, no re-collision next pass', () => {
  const state = oneBrickState({
    x: 136, y: 95, r: BALL_R, vx: 0, vy: 300, prevX: 136, prevY: 90,
  });
  resolveBrickCollisions(state);
  assert.ok(!collides(state.ball, state.bricks[0]), 'ball no longer overlaps');
  const vyAfter = state.ball.vy;
  const scoreAfter = state.score;
  // Second pass: ball now moves away from the brick (vy < 0).
  state.ball.prevX = state.ball.x;
  state.ball.prevY = state.ball.y;
  state.ball.y += state.ball.vy * 0.01;
  resolveBrickCollisions(state);
  assert.equal(state.ball.vy, vyAfter, 'no double flip');
  assert.equal(state.score, scoreAfter, 'brick counted once');
});

test('brick: two bricks on a seam flip vy only once', () => {
  // Two bricks stacked with BRICK_H + BRICK_GAP spacing; the ball overlaps
  // both mid-pass. Only the first-hit brick may be destroyed and vy flips
  // exactly once — two -vy flips would cancel out and tunnel.
  const top = { x: 100, y: 100, w: 72, h: 20, alive: true, row: 0, points: 50 };
  const bottom = { x: 100, y: 128, w: 72, h: 20, alive: true, row: 1, points: 40 };
  const state = {
    score: 0, combo: 0, bricks: [top, bottom],
    ball: { x: 136, y: 124, r: BALL_R, vx: 0, vy: 300, prevX: 136, prevY: 90 },
  };
  resolveBrickCollisions(state);
  assert.equal(Math.sign(state.ball.vy), UP, 'single bounce, not a double flip');
  assert.equal(top.alive, false, 'first-hit brick destroyed');
  assert.equal(bottom.alive, true, 'second brick left for the next pass');
});

test('brick: no tunneling — a full-speed step at level 6 still bounces', () => {
  // Max travel per frame vs. brick height + ball diameter: at level 6 the
  // frame step (35.5 px) exceeds 34 px, so a discrete end-of-frame check
  // would skip the brick entirely.
  const level = 6;
  const speed = ballSpeed(level);
  const travel = speed * 0.05; // dt is capped at 50 ms
  assert.ok(travel > BRICK_H + 2 * BALL_R, 'precondition: frame step beats the brick');
  const state = oneBrickState({
    x: 136, y: 100 - 8 + travel, r: BALL_R, vx: 0, vy: speed,
    prevX: 136, prevY: 100 - 8,
  });
  // End position is past the brick's far edge (no overlap at frame end).
  assert.ok(!collides(state.ball, state.bricks[0]), 'precondition: discrete check misses');
  resolveBrickCollisions(state);
  assert.equal(Math.sign(state.ball.vy), UP, 'ball bounces instead of tunneling');
  assert.equal(state.bricks[0].alive, false, 'brick was hit');
  assert.ok(state.ball.y < 100, 'ball ended up above the brick');
});

