export function collides(ball, brick) {
  return (
    ball.x + ball.r > brick.x &&
    ball.x - ball.r < brick.x + brick.w &&
    ball.y + ball.r > brick.y &&
    ball.y - ball.r < brick.y + brick.h
  );
}

// Resolves ball–brick collisions for one pass: destroys the hit brick,
// awards score/combo, bounces the ball off the face it hit (smallest
// penetration; a corner flips both components) and pushes the ball out of the
// brick so it can never be re-caught on the next pass.
//
// Swept test: the ball is moved by `step()` from (prevX, prevY) to its
// current position; we test the whole travel segment against each brick's
// inflated box instead of only the end position, so a fast ball cannot skip
// over a brick between two frames (see the level-6 tunneling case).
// One brick per pass: if the segment enters two bricks of a seam, only the
// first entry (smallest t) is resolved — a second flip would cancel the first
// and the ball would tunnel through.
export function resolveBrickCollisions(state) {
  const { ball, bricks } = state;

  let hit = null;
  for (const brick of bricks) {
    if (!brick.alive) continue;
    const entry = sweptEntry(ball, brick);
    if (!entry) continue;
    if (!hit || entry.t < hit.t) hit = entry;
  }
  if (!hit) return;

  const { brick, face, corner } = hit;
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  if (corner) {
    // Corner hit: both components invert. Park the ball on the corner of the
    // inflated box, i.e. exactly one radius away from the brick on both axes.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = hit.x !== undefined ? hit.x :
      (ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r);
    ball.y = hit.y !== undefined ? hit.y :
      (ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r);
  } else if (face === 'top') {
    ball.y = brick.y - ball.r;
    ball.vy = -Math.abs(ball.vy);
  } else if (face === 'bottom') {
    ball.y = brick.y + brick.h + ball.r;
    ball.vy = Math.abs(ball.vy);
  } else if (face === 'left') {
    ball.x = brick.x - ball.r;
    ball.vx = Math.abs(ball.vx);
  } else if (face === 'right') {
    ball.x = brick.x + brick.w + ball.r;
    ball.vx = -Math.abs(ball.vx);
  }
}

// First entry point (t ∈ (0, 1]) of the ball's travel segment into the brick's
// inflated box [x-r, x+w+r] × [y-r, y+h+r], plus the face being crossed and
// whether both slabs are crossed at the same instant (a corner). Returns null
// when the segment never enters the box.
function sweptEntry(ball, brick) {
  const { r } = ball;
  const x0 = brick.x - r;
  const x1 = brick.x + brick.w + r;
  const y0 = brick.y - r;
  const y1 = brick.y + brick.h + r;
  const px = ball.prevX;
  const py = ball.prevY;
  const dx = ball.x - px;
  const dy = ball.y - py;

  // The ball is already strictly inside the inflated box at frame start
  // (leftover overlap): resolve from the penetration depths instead.
  if (px > x0 && px < x1 && py > y0 && py < y1) {
    return overlapEntry(ball, brick);
  }

  let tmin = 0;
  let tmax = 1;
  let face = null;
  let corner = false;

  // X slab
  if (dx === 0) {
    if (px < x0 || px > x1) return null;
  } else {
    let t1 = (x0 - px) / dx;
    let t2 = (x1 - px) / dx;
    if (t1 > t2) {
      const swap = t1;
      t1 = t2;
      t2 = swap;
    }
    if (t1 > tmin) {
      tmin = t1;
      face = dx > 0 ? 'left' : 'right';
    } else if (t1 === tmin && face !== null) {
      corner = true; // both slabs reached at the same t: corner entry
    }
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return null;
  }

  // Y slab
  if (dy === 0) {
    if (py < y0 || py > y1) return null;
  } else {
    let t1 = (y0 - py) / dy;
    let t2 = (y1 - py) / dy;
    if (t1 > t2) {
      const swap = t1;
      t1 = t2;
      t2 = swap;
    }
    if (t1 > tmin) {
      tmin = t1;
      face = dy > 0 ? 'top' : 'bottom';
    } else if (t1 === tmin && face !== null) {
      corner = true;
    }
    tmax = Math.min(tmax, t2);
    if (tmin > tmax) return null;
  }

  // No real entry: the ball only touched the box boundary (e.g. resting on a
  // face after the previous bounce) or the entry lies beyond this frame.
  if (tmin <= 0 || tmin > 1 || face === null) return null;

  return {
    brick,
    t: tmin,
    face,
    corner,
    x: px + dx * tmin,
    y: py + dy * tmin,
  };
}

// Ball already inside the inflated box: the face is the one with the smallest
// penetration; equal penetrations mean a corner (both components flip).
function overlapEntry(ball, brick) {
  const penLeft = ball.x + ball.r - brick.x;
  const penRight = brick.x + brick.w + ball.r - ball.x;
  const penTop = ball.y + ball.r - brick.y;
  const penBottom = brick.y + brick.h + ball.r - ball.y;
  const min = Math.min(penLeft, penRight, penTop, penBottom);
  const faces = [];
  if (penLeft === min) faces.push('left');
  if (penRight === min) faces.push('right');
  if (penTop === min) faces.push('top');
  if (penBottom === min) faces.push('bottom');
  return { brick, t: 0, face: faces[0], corner: faces.length > 1 };
}

