+// Resolves ball–brick collisions for one pass: destroys the hit brick,
+// awards score/combo, bounces the ball off the face it hit (smallest
+// penetration; a corner flips both components) and pushes the ball out of the
+// brick so it can never be re-caught on the next pass.
+//
+// Swept test: the ball is moved by `step()` from (prevX, prevY) to its
+// current position; we test the whole travel segment against each brick's
+// inflated box instead of only the end position, so a fast ball cannot skip
+// over a brick between two frames (see the level-6 tunneling case).
+// One brick per pass: if the segment enters two bricks of a seam, only the
+// first entry (smallest t) is resolved — a second flip would cancel the first
+// and the ball would tunnel through.
+export function resolveBrickCollisions(state) {
+  const { ball, bricks } = state;
+
+  let hit = null;
+  for (const brick of bricks) {
+    if (!brick.alive) continue;
+    const entry = sweptEntry(ball, brick);
+    if (!entry) continue;
+    if (!hit || entry.t < hit.t) hit = entry;
+  }
+  if (!hit) return;
+
+  const { brick, face, corner } = hit;
+  brick.alive = false;
+  state.combo += 1;
+  state.score += scoreForBrick(brick, state.combo);
